# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.16.1/ankra-cli-darwin-arm64"
      sha256 "d3d8c348afc69a13b13f6530bc764e4ccdaa2127cd90b854c140774c906516eb"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.16.1/ankra-cli-darwin-amd64"
      sha256 "fb5a3af390fe57d6e416a85fcdb506f8b39c2a5c4a297db7fed594deab3bfb36"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.16.1/ankra-cli-linux-arm64"
      sha256 "464ce331be4e49431be87e5cf2e67d133eb37765368592fea593e721414c14ea"
    end
    on_intel do
